+// Reproduce the review's first-page allocation probe on macOS.
+// Usage: bun profile-recall.mjs CLI_ROOT LABEL OUTPUT_JSON
+import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
